True def transform(grid):
    """Fill cells between consecutive equal non-background markers in rows/columns."""
    g = [row[:] for row in grid]
    from collections import Counter
    counts = Counter(x for row in g for x in row)
    bg = counts.most_common(1)[0][0]
    h, w = len(g), len(g[0])
    # ARC examples have one sparse marker color; infer it as the non-background color.
    colors = [c for c in counts if c != bg]
    for color in colors:
        for r in range(h):
            xs = [c for c in range(w) if g[r][c] == color]
            for a, b in zip(xs, xs[1:]):
                for c in range(a+1, b):
                    if g[r][c] == bg:
                        g[r][c] = 3
        for c in range(w):
            ys = [r for r in range(h) if g[r][c] == color]
            for a, b in zip(ys, ys[1:]):
                for r in range(a+1, b):
                    if g[r][c] == bg:
                        g[r][c] = 3
    return g
